//! ICMPv6 messages generated by the router (RFC 4443): echo replies and the
//! error messages used by forwarding. Neighbor Discovery messages live in
//! `ndp.zig`; both use the IPv6 pseudo-header checksum implemented here.

const std = @import("std");
const ipv6 = @import("ipv6.zig");
const types = @import("vnet-core").types;

pub const Type = struct {
    pub const destination_unreachable: u8 = 1;
    pub const packet_too_big: u8 = 2;
    pub const time_exceeded: u8 = 3;
    pub const parameter_problem: u8 = 4;
    pub const echo_request: u8 = 128;
    pub const echo_reply: u8 = 129;
    pub const router_solicitation: u8 = 133;
    pub const router_advertisement: u8 = 134;
    pub const neighbor_solicitation: u8 = 135;
    pub const neighbor_advertisement: u8 = 136;
    pub const redirect: u8 = 137;
};

pub const Code = struct {
    pub const no_route: u8 = 0;
    pub const admin_prohibited: u8 = 1;
    pub const beyond_scope: u8 = 2;
    pub const address_unreachable: u8 = 3;
    pub const port_unreachable: u8 = 4;
    pub const hop_limit_exceeded: u8 = 0;
    pub const reassembly_timeout: u8 = 1;
    pub const err_header_field: u8 = 0;
    pub const unrecognized_next_header: u8 = 1;
    pub const unrecognized_option: u8 = 2;
};

pub const Error = error{
    Truncated,
    NotIpv6,
    NotEchoRequest,
    NoSpace,
};

pub const Header = struct {
    typ: u8,
    code: u8,
    /// Message bytes starting at the checksum field.
    body: []const u8,
};

pub fn parse(payload: []const u8) Error!Header {
    if (payload.len < 4) return error.Truncated;
    return .{ .typ = payload[0], .code = payload[1], .body = payload[2..] };
}

pub fn verifyChecksum(src: types.Ipv6, dst: types.Ipv6, message: []const u8) bool {
    if (message.len < 4) return false;
    return ipv6.checksum(src, dst, ipv6.Protocol.icmpv6, message) == 0;
}

pub fn writeEchoRequest(
    buf: []u8,
    src: types.Ipv6,
    dst: types.Ipv6,
    id: u16,
    seq: u16,
    payload: []const u8,
) Error!usize {
    const total = 8 + payload.len;
    if (buf.len < total) return error.NoSpace;

    buf[0] = Type.echo_request;
    buf[1] = 0;
    writeU16(buf, 2, 0);
    writeU16(buf, 4, id);
    writeU16(buf, 6, seq);
    @memcpy(buf[8..total], payload);
    writeU16(buf, 2, ipv6.checksum(src, dst, ipv6.Protocol.icmpv6, buf[0..total]));
    return total;
}

pub fn writeEchoReply(
    buf: []u8,
    src: types.Ipv6,
    dst: types.Ipv6,
    request: []const u8,
) Error!usize {
    if (request.len < 8) return error.Truncated;
    if (request[0] != Type.echo_request) return error.NotEchoRequest;
    if (buf.len < request.len) return error.NoSpace;

    @memcpy(buf[0..request.len], request);
    buf[0] = Type.echo_reply;
    writeU16(buf, 2, 0);
    writeU16(buf, 2, ipv6.checksum(src, dst, ipv6.Protocol.icmpv6, buf[0..request.len]));
    return request.len;
}

/// Builds an ICMPv6 error quoting the invoking IPv6 packet. `rest` carries the
/// MTU for Packet Too Big or the pointer for Parameter Problem.
pub fn writeError(
    buf: []u8,
    src: types.Ipv6,
    dst: types.Ipv6,
    typ: u8,
    code: u8,
    original: []const u8,
    rest: u32,
) Error!usize {
    if (original.len < 40) return error.Truncated;
    if (original[0] >> 4 != 6) return error.NotIpv6;

    const max_quote: usize = 1280 - 40 - 8;
    const quoted_len = @min(original.len, max_quote);
    const total = 8 + quoted_len;
    if (buf.len < total) return error.NoSpace;

    buf[0] = typ;
    buf[1] = code;
    writeU16(buf, 2, 0);
    writeU32(buf, 4, rest);
    @memcpy(buf[8..total], original[0..quoted_len]);
    writeU16(buf, 2, ipv6.checksum(src, dst, ipv6.Protocol.icmpv6, buf[0..total]));
    return total;
}

fn writeU16(buf: []u8, off: usize, value: u16) void {
    buf[off] = @truncate(value >> 8);
    buf[off + 1] = @truncate(value);
}

fn writeU32(buf: []u8, off: usize, value: u32) void {
    buf[off] = @truncate(value >> 24);
    buf[off + 1] = @truncate(value >> 16);
    buf[off + 2] = @truncate(value >> 8);
    buf[off + 3] = @truncate(value);
}

const testing = std.testing;

fn testSrc() types.Ipv6 {
    return types.Ipv6.parse("2001:db8:1::1") catch unreachable;
}

fn testDst() types.Ipv6 {
    return types.Ipv6.parse("2001:db8:2::1") catch unreachable;
}

test "icmpv6 echo request and reply round trip" {
    var request: [128]u8 = undefined;
    const n = try writeEchoRequest(&request, testSrc(), testDst(), 0x1234, 7, "payload");
    try testing.expect(verifyChecksum(testSrc(), testDst(), request[0..n]));

    var reply: [128]u8 = undefined;
    const m = try writeEchoReply(&reply, testDst(), testSrc(), request[0..n]);
    try testing.expectEqual(n, m);
    try testing.expectEqual(Type.echo_reply, reply[0]);
    try testing.expect(verifyChecksum(testDst(), testSrc(), reply[0..m]));
    try testing.expectEqualSlices(u8, request[8..n], reply[8..m]);
}

test "icmpv6 echo reply rejects non-requests" {
    var buf: [16]u8 = @splat(0);
    try testing.expectError(error.Truncated, writeEchoReply(&buf, testSrc(), testDst(), buf[0..7]));

    buf[0] = Type.echo_reply;
    try testing.expectError(error.NotEchoRequest, writeEchoReply(&buf, testSrc(), testDst(), &buf));
}

test "icmpv6 error quotes the invoking packet" {
    var packet: [128]u8 = undefined;
    const n = try ipv6.write(&packet, testSrc(), testDst(), ipv6.Protocol.udp, 64, "0123456789");

    var msg: [1280]u8 = undefined;
    const m = try writeError(
        &msg,
        testDst(),
        testSrc(),
        Type.destination_unreachable,
        Code.address_unreachable,
        packet[0..n],
        0,
    );
    try testing.expectEqual(@as(usize, 8 + n), m);
    try testing.expect(verifyChecksum(testDst(), testSrc(), msg[0..m]));
    try testing.expectEqualSlices(u8, packet[0..n], msg[8..m]);
}

test "icmpv6 packet too big carries mtu" {
    var packet: [64]u8 = undefined;
    const n = try ipv6.write(&packet, testSrc(), testDst(), ipv6.Protocol.udp, 64, "x");

    var msg: [1280]u8 = undefined;
    const m = try writeError(&msg, testDst(), testSrc(), Type.packet_too_big, 0, packet[0..n], 1280);
    try testing.expectEqual(@as(u32, 1280), readU32(msg[0..m], 4));
    try testing.expect(verifyChecksum(testDst(), testSrc(), msg[0..m]));
}

fn readU32(buf: []const u8, off: usize) u32 {
    return (@as(u32, buf[off]) << 24) |
        (@as(u32, buf[off + 1]) << 16) |
        (@as(u32, buf[off + 2]) << 8) |
        buf[off + 3];
}
